export default {
  id: 'event-counter',
  name: 'Event Counter',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    // 本实例变量：保存监听器最近观察到的 counter.value
    let lastObserved: number | null = null;

    // 注册 listener 监听 counter.value 事件
    ctx.register({
      kind: 'listener',
      event: 'counter.value',
      listener: (event: { data?: unknown }) => {
        const data = event?.data as { value?: unknown } | undefined;
        if (data && typeof data.value === 'number') {
          lastObserved = data.value;
        }
      },
    });

    // 注册 emit_value 工具：发射值 27 并返回监听器观察到的值
    ctx.register({
      kind: 'tool',
      tool: {
        name: 'emit_value',
        version: '1.0.0',
        description: 'Emit counter.value=27 on the bus and return the value observed by the listener.',
        permissions: [],
        sideEffect: 'none',
        parameters: {
          type: 'object',
          properties: {
            value: { type: 'number', description: 'Value to emit (defaults to 27).' },
          },
        },
        outputSchema: {
          type: 'object',
          properties: {
            emitted: { type: 'number' },
            observed: { type: ['number', 'null'] },
          },
          required: ['emitted', 'observed'],
        },
        async handler(args: unknown) {
          const { value } = (args ?? {}) as { value?: number };
          const emitted = typeof value === 'number' ? value : 27;
          // 发射事件，监听器同步更新 lastObserved
          ctx.bus.emit({ type: 'counter.value', ts: Date.now(), data: { value: emitted } });
          return { ok: true, data: { emitted, observed: lastObserved } };
        },
      },
    });
  },
};

export default {
  id: 'event-counter',
  name: 'Event Counter',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    // 本实例变量：保存监听器最近观察到的 counter.value
    let lastObserved: number | null = null;

    const capture = (event: { data?: unknown }) => {
      const data = event?.data as { value?: unknown } | undefined;
      if (data && typeof data.value === 'number') {
        lastObserved = data.value;
      }
    };

    // 注册 listener 能力监听 counter.value 事件
    ctx.register({
      kind: 'listener',
      event: 'counter.value',
      listener: capture,
    });

    // 同时通过 ctx.on 订阅总线，确保能捕获 ctx.bus.emit 派发的事件
    ctx.on('counter.value', capture);

    // 注册 emit_value 工具：发射值 27 并返回监听器观察到的值
    ctx.register({
      kind: 'tool',
      tool: {
        name: 'emit_value',
        version: '1.0.0',
        description: 'Emit counter.value=27 on the bus and return the value observed by the listener.',
        permissions: [],
        sideEffect: 'none',
        parameters: {
          type: 'object',
          properties: {
            value: { type: 'number', description: 'Value to emit (defaults to 27).' },
          },
        },
        outputSchema: {
          type: 'object',
          properties: {
            emitted: { type: 'number' },
            observed: { type: ['number', 'null'] },
          },
          required: ['emitted', 'observed'],
        },
        async handler(args: unknown) {
          const { value } = (args ?? {}) as { value?: number };
          const emitted = typeof value === 'number' ? value : 27;
          // 发射事件；若派发为异步，则等待其完成后再读取观察值
          const result = ctx.bus.emit({ type: 'counter.value', ts: Date.now(), data: { value: emitted } });
          if (result && typeof (result as { then?: unknown }).then === 'function') {
            await result;
          } else {
            await Promise.resolve();
          }
          return { ok: true, data: { emitted, observed: lastObserved } };
        },
      },
    });
  },
};

